from pathlib import Path
import json,csv,sys,html
ROOT=Path(__file__).resolve().parents[3];sys.path.insert(0,str(ROOT))
from icon_set.model.icons.registry import create
W=Path(__file__).parent
SOURCE_ICON_ID=None
SOURCE_PATH='icon_set/work/local-width-audit/results.json'
AUTHOR='gpt-6'
rows=json.loads((W/'results.json').read_text());flagged=[r for r in rows if r['status']=='review'];cards=[]
with (W/'flagged-icons.csv').open('w') as f:
 writer=csv.writer(f);writer.writerow(['icon_id','current_status','existing_internal_review','maximum_narrow_run','minimum_sampled_ink_gap','file'])
 for r in flagged:
  writer.writerow([r['id'],r['baseline_status'],r['baseline_internal_review'],r['narrow_run_max'],min(x['ink_gap'] for x in r['findings']),r['file']])
for r in sorted(flagged,key=lambda r:(r['baseline_status']!='pass',r['id'])):
 svg=create(r['id']).to_svg();overlay=[]
 for finding in r['findings']:
  pts=' '.join(f'{x:.3f},{y:.3f}' for x,y in finding['run_points']);a,b=finding['nearest_points']
  overlay.append(f'<polyline points="{pts}" fill="none" stroke="#dc4929" stroke-width="0.8"/><path d="M{a[0]} {a[1]}L{b[0]} {b[1]}" stroke="#146aaa" stroke-width="0.4"/>')
 overlay='<svg viewBox="0 0 48 48" class="overlay">'+''.join(overlay)+'</svg>'
 details=''.join(f'<li>{html.escape(" ↔ ".join(f["elements"]))}: {f["ink_gap"]:.2f}px gap for {f["sustained_length"]:.2f}px</li>' for f in r['findings'])
 cards.append(f'''<article data-name="{r['id']}" data-baseline="{r['baseline_status']}" data-old="{str(r['baseline_internal_review']).lower()}" data-length="{r['narrow_run_max']}"><h2>{r['id']}</h2><div class="drawing">{svg}{overlay}</div><p>Current: <b>{r['baseline_status']}</b> · Previous internal review: <b>{'yes' if r['baseline_internal_review'] else 'no'}</b></p><p>Longest narrow stretch: {r['narrow_run_max']:.2f}px</p><details><summary>Measurements</summary><ul>{details}</ul></details></article>''')
(W/'index.html').write_text('''<!doctype html><html><head><meta charset="utf-8"><title>Local-width audit</title><style>body{font:15px system-ui;color:#24272d;background:#f7f6f2;margin:28px}header{max-width:1000px}h1{font-size:28px}h2{font-size:15px;overflow-wrap:anywhere}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:15px}article{background:white;border:1px solid #ddd;border-radius:12px;padding:16px}article[hidden]{display:none}.drawing{position:relative;width:144px;height:144px;margin:15px auto}.drawing>svg{position:absolute;inset:0;width:100%;height:100%}p,li,summary{font-size:13px}li{margin-bottom:7px}nav{position:sticky;top:0;padding:15px 0;background:#f7f6f2;z-index:2;display:flex;gap:10px;flex-wrap:wrap}input,select{padding:8px;border:1px solid #ccc;border-radius:6px}a{color:#175cab}.note{color:#705100}</style></head><body><header><h1>Experimental local-width audit</h1><p>5,288 solo icons scanned, including variants. 625 flagged at a 2px minimum narrow-run length; 325 currently pass gallery QA. 260 of these flags were absent from the older internal-spacing checker. No source changes or scan errors were observed during this snapshot.</p><p class="note">These are review candidates, not confirmed design failures. Existing production rules and icon drawings are unchanged. Red = sustained narrow region; blue = sampled distance across it. Negative clear gaps indicate opposing strokes overlap.</p><p>Trial parameters: 0.25px samples, 8px centerline / 4px clear-ink requirement, 8px local contour-distance exclusion, opposing-boundary direction filter, unobstructed centerline connector. Complete circles are delegated to existing hole checks. This sampled prototype is not a certified geometric distance gate; threshold tuning and visual review remain necessary.</p><p><a href="four-examples.png">Your four examples</a> · <a href="flagged-icons.csv">Download all 625 flags</a> · <a href="summary.json">Summary</a></p></header><nav><input id="q" placeholder="Search icon"><select id="baseline"><option value="">All current statuses</option><option>pass</option><option>fail</option><option>review</option></select><select id="old"><option value="">All findings</option><option value="false">Missed by old checker</option><option value="true">Old checker also flagged</option></select><select id="length"><option value="2">At least 2px narrow</option><option value="4">At least 4px narrow</option><option value="6">At least 6px narrow</option></select><strong id="count"></strong></nav><main>'''+''.join(cards)+'''</main><script>const q=document.querySelector('#q'),baseline=document.querySelector('#baseline'),old=document.querySelector('#old'),length=document.querySelector('#length');function filter(){let n=0;document.querySelectorAll('article').forEach(c=>{let show=c.dataset.name.includes(q.value.toLowerCase())&&(!baseline.value||c.dataset.baseline===baseline.value)&&(!old.value||c.dataset.old===old.value)&&Number(c.dataset.length)>=Number(length.value);c.hidden=!show;n+=show;});document.querySelector('#count').textContent=n+' icons';}for(const e of [q,baseline,old,length])e.addEventListener('input',filter);filter();</script></body></html>''')
print('Wrote interactive audit and CSV for',len(flagged),'icons')
# Quantify overlap without accidentally claiming this prototype supersedes all old checks.
union=[r for r in rows if r.get('baseline_internal_review') or r['status']=='review']
print('Union with existing internal review:',len(union),'including',sum(r.get('baseline_status')=='pass' for r in union),'currently pass')
print('Current pass baseline total:',sum(r.get('baseline_status')=='pass' for r in rows))
